 {
        cdf_property_info_t *inp;
        size_t newcount = *maxcount + incr;

        if (newcount > CDF_PROP_LIMIT) {
                DPRINTF(("exceeded property limit %" SIZE_T_FORMAT "u > %"
                    SIZE_T_FORMAT "u\n", newcount, CDF_PROP_LIMIT));
                goto out;
